def encode_shift(text: str) -> str:
    """Shift each lowercase letter in `text` forward by 5 positions cyclically."""
    return ''.join(
        chr((ord(c) - 97 + 5) % 26 + 97) if 'a' <= c <= 'z' else c
        for c in text
    )

def decode_shift(text: str) -> str:
    """Reverse the `encode_shift` operation, shifting each lowercase letter backward by 5."""
    return ''.join(
        chr((ord(c) - 97 - 5) % 26 + 97) if 'a' <= c <= 'z' else c
        for c in text
    )

