    """
    Finds all (row, col) positions where lst[row][col] equals x,
    scanning each row backwards (from last column to first).
    """
    return [
        (row_idx, col_idx)
        for row_idx, row in enumerate(lst)
        for col_idx in range(len(row) - 1, -1, -1)
        if row[col_idx] == x
