def has_close_numbers(nums, threshold):
    """
    Sorts the numbers, then iterates through adjacent pairs to check if any
    difference is less than the threshold. Returns true if found, false otherwise.
    """
    if not nums:
        return False

    # Sort the numbers
    sorted_nums = sorted(nums)

    # Use a generator expression with any() to check adjacent differences
    return any(
        abs(sorted_nums[i] - sorted_nums[i + 1]) < threshold
        for i in range(len(sorted_nums) - 1)
    )

