def encode_shift(s: str) -> str:
    """
    Encode a lowercase-only string by shifting every a-z letter 5 places forward.
    Non-letters are ignored and the input is treated as lowercase.
    """
    return ''.join(
        chr((ord(c) - ord('a') + 5) % 26 + ord('a'))
        for c in s.lower()
        if 'a' <= c <= 'z'
    )


def decode_shift(s: str) -> str:
    """
    Decode a string that was encoded with encode_shift by shifting every a-z
    letter 5 places backward. Non-letters are ignored.
    """
    return ''.join(
        chr((ord(c) - ord('a') - 5) % 26 + ord('a'))
        for c in s.lower()
        if 'a' <= c <= 'z'
    )
