def has_three_sum_zero(nums):
    # Convert to set to get unique elements
    unique_nums = list(set(nums))
    n = len(unique_nums)

    # Need at least 3 elements
    if n < 3:
        return False

    # Check all triplets
    return any(
        unique_nums[i] + unique_nums[j] + unique_nums[k] == 0
        for i in range(n - 2)
        for j in range(i + 1, n - 1)
        for k in range(j + 1, n)
    )
